using System;using System.Linq;using System.Threading.Tasks;using UnityEngine;using AntColony.Core;using AntColony.Units;using AntColony.UI;
public static class Seat1114Exit {public static async Task<string> Run(){var c=CommanderRoster.Instance.Commanders.First(x=>x&&x.IsEating&&x.MealTable);c.PersonalState.meal.eatSeconds=.1f;SimulationPause.UserSpeed(1);await Task.Delay(500);if(!c.Agent.updatePosition||c.MealTable)throw new Exception("Seat navigation not released");var start=c.Position;var p=c.Agent.nextPosition+Vector3.back*3;if(!c.CanReach(p))throw new Exception("Fixture exit unreachable");c.CommandMove(p);await Task.Delay(700);SimulationPause.UserSpeed(0);var motion=c.GetComponent<MeshyNativeMotionPlayer>().PlayingMotion;if(Vector3.Distance(start,c.Position)<.3f)throw new Exception("No exit movement");return "PASS seat release: agent restored, moved="+Vector3.Distance(start,c.Position)+" native="+motion;}}
